// sng_lut.sv
//
// Threshold lookup table for one SNG (the "LUT" and "T" blocks in Fig. 1 of
// the proposal). Entry k holds T_k = round(P_switch(V_k) * (2^16 - 1)) for
// voltage code k, generated by Python_Code/switchingmodel.py.
//
// LUT_FILE: .mem file loaded with $readmemh, one 4-digit hex value per line.
//           Each SNG gets its own file (lut_a/b/s.mem) to emulate
//           device-to-device variation.
//
// The read is synchronous and only happens while rd_en is high, so Vivado
// infers block RAM, and the output register holds T for the whole run. That
// register is the latched "T" block, so no separate threshold register is
// needed.

module sng_lut #(
    parameter string LUT_FILE = "lut_a.mem",
    parameter int    DEPTH    = 2048,
    parameter int    WIDTH    = 16
) (
    input  logic                     clk,
    input  logic                     rd_en,  // latch rom[addr] into data
    input  logic [$clog2(DEPTH)-1:0] addr,   // voltage code
    output logic [WIDTH-1:0]         data    // threshold T
);

    // ---- Table storage ----
    //
    // DEPTH entries of WIDTH bits each: 2048 x 16 = 32 Kbit, one BRAM-sized
    // table per SNG. rom[k] is the threshold for voltage code k.
    logic [WIDTH-1:0] rom [DEPTH];

    // ---- Table contents ----
    //
    // Fill rom from the .mem file when the design is elaborated. In Vivado
    // this becomes the BRAM's initial contents in the bitstream; in
    // simulation it runs once at time 0. The hardware never writes rom, so
    // it behaves as a ROM.
    initial $readmemh(LUT_FILE, rom);

    // ---- Threshold read / latch ----
    //
    // On a clock edge with rd_en high, copy the entry for addr into data.
    // With rd_en low, data keeps its old value, so the threshold stays
    // fixed for the whole run even if addr changes. A registered read like
    // this is what lets Vivado map rom onto block RAM instead of LUT logic.
    always_ff @(posedge clk)
        if (rd_en)
            data <= rom[addr];
        // Otherwise hold T.

endmodule
